/* ============================================================
   Dansk Drill — card data.

   Embedded as a plain JS global on purpose: no fetch(), no JSON file,
   so index.html works by double-clicking it (file:// blocks fetch).

   SCOPE: all of Module 1 (Parts 1–6), Module 2 Kapitel 1–2, the ungated
   Resources, and Anshu's own notes up to 2026-11-15.

   Card shapes
     flip      { id, category, type, front, back, phonetic?, examples?, note? }
     conjugate { id, category, type, prompt, acceptedAnswers[], exampleSentence,
                 exampleTranslation, note? }
     reorder   { id, category, type, sentence, translation, startWith?,
                 altSentences?, note? }
     sentence  { id, category, type, prompt, promptLang, modelAnswer, hint?, note? }

   `phonetic` is a rough plain-English anchor, editable in the app and
   exported for hand-copying back into the markdown notes. Where Anshu's
   own notes already had a guess, that guess is used verbatim.
   ============================================================ */

